CREATE TABLE "knowledge_ingestion_candidates" ("id" text PRIMARY KEY NOT NULL, "ingestion_job_id" text NOT NULL, "source_id" text NOT NULL, "capture_version_id" text NOT NULL, "fingerprint" text NOT NULL, "type" text NOT NULL, "title" text NOT NULL, "summary" text NOT NULL, "location_name" text, "route_segment" text, "conditions" jsonb DEFAULT '[]'::jsonb NOT NULL, "freshness_sensitive" boolean DEFAULT false NOT NULL, "span_start" integer NOT NULL, "span_end" integer NOT NULL, "extraction_model_id" text, "extraction_prompt_version" text NOT NULL, "stage" text DEFAULT 'queued' NOT NULL, "stage_version" integer DEFAULT 1 NOT NULL, "attempt_count" integer DEFAULT 0 NOT NULL, "max_attempts" integer DEFAULT 3 NOT NULL, "next_run_at" timestamp DEFAULT now() NOT NULL, "claimed_by" text, "claimed_at" timestamp, "lease_expires_at" timestamp, "fencing_token" text, "outcome_reason_code" text, "judgment_summary" text, "scores" jsonb, "knowledge_card_id" text, "created_at" timestamp DEFAULT now() NOT NULL, "updated_at" timestamp DEFAULT now() NOT NULL, CONSTRAINT "knowledge_ingestion_candidates_ingestion_job_id_knowledge_ingestion_jobs_id_fk" FOREIGN KEY ("ingestion_job_id") REFERENCES "knowledge_ingestion_jobs"("id") ON DELETE cascade, CONSTRAINT "knowledge_ingestion_candidates_source_id_sources_id_fk" FOREIGN KEY ("source_id") REFERENCES "sources"("id") ON DELETE restrict, CONSTRAINT "knowledge_ingestion_candidates_extraction_model_id_ai_gateway_models_id_fk" FOREIGN KEY ("extraction_model_id") REFERENCES "ai_gateway_models"("id") ON DELETE set null, CONSTRAINT "knowledge_ingestion_candidates_knowledge_card_id_knowledge_cards_id_fk" FOREIGN KEY ("knowledge_card_id") REFERENCES "knowledge_cards"("id") ON DELETE set null, CONSTRAINT "knowledge_ingestion_candidates_capture_version_source_fk" FOREIGN KEY ("capture_version_id","source_id") REFERENCES "source_capture_versions"("id","source_id") ON DELETE restrict, CONSTRAINT "knowledge_ingestion_candidates_stage_check" CHECK ("stage" in ('queued', 'judging', 'relating', 'published', 'suppressed', 'review_recommended', 'verify_first', 'failed')), CONSTRAINT "knowledge_ingestion_candidates_span_check" CHECK ("span_start" >= 0 and "span_end" > "span_start"), CONSTRAINT "knowledge_ingestion_candidates_safe_text_check" CHECK (length(btrim("title")) between 1 and 160 and length(btrim("summary")) between 1 and 1200 and length(btrim("extraction_prompt_version")) between 1 and 160), CONSTRAINT "knowledge_ingestion_candidates_conditions_check" CHECK (jsonb_typeof("conditions") = 'array'), CONSTRAINT "knowledge_ingestion_candidates_attempt_check" CHECK ("attempt_count" >= 0 and "attempt_count" <= "max_attempts" and "max_attempts" between 1 and 10), CONSTRAINT "knowledge_ingestion_candidates_claim_shape_check" CHECK (("claimed_by" is null and "claimed_at" is null and "lease_expires_at" is null and "fencing_token" is null) or ("claimed_by" is not null and "claimed_at" is not null and "lease_expires_at" > "claimed_at" and "fencing_token" ~ '^[a-f0-9]{64}$')));--> statement-breakpoint
CREATE UNIQUE INDEX "knowledge_ingestion_candidates_job_fingerprint_idx" ON "knowledge_ingestion_candidates" USING btree ("ingestion_job_id","fingerprint");--> statement-breakpoint
CREATE INDEX "knowledge_ingestion_candidates_claim_queue_idx" ON "knowledge_ingestion_candidates" USING btree ("stage","next_run_at","created_at");--> statement-breakpoint
CREATE INDEX "knowledge_ingestion_candidates_parent_stage_idx" ON "knowledge_ingestion_candidates" USING btree ("ingestion_job_id","stage");--> statement-breakpoint
CREATE INDEX "knowledge_ingestion_candidates_capture_span_idx" ON "knowledge_ingestion_candidates" USING btree ("capture_version_id","span_start");
